/************************************************************************
 render wallet, perform calculations
************************************************************************/
		function renderCart(items) {
			const $cart = document.querySelector(".cart")
			const $total = document.querySelector(".total")
			const $totalQuantity = document.querySelector(".total-quantity")
			let totalQuantity = 0

			//DIMI sort by date first, before populating the cart (see _HELP/Javascript)
			const sortByDate = (items) => 
			  items.sort (({date: a}, {date: b}) => a < b ? -1 : a > b ? 1 : 0)
			  sortByDate (items)
			//console.log(sortByDate (items));
			
			/* DIMI remove duplicates like "Dolphin show VIP seats Erwachsene: 1, Dolphin show VIP seats Kinder: 1"
			 * MUST be inside renderCart() function and MUST execute on doc ready
			 */
			$(function() {
				var prev;
				$('#wallet div.dterm').each(function() {
				  var text = $(this).text().trim();
				  if (prev == text)
					$(this).remove();
				  
				  prev = text;
				});
			});
				
			$cart.innerHTML = items.map((item) => {
				totalQuantity += item.quantity
				return `
					<tr class="item-list">
						<td><div class="item-date d-flex flex-column"><div class="d-flex align-items-center justify-content-center"><span class="tealColor fs-3">${item.day}</span></div> <p class="text-center m-0 p-0 fs-8 tealColor">${item.month}</p></div></td>
						<td class="d-none">#${item.id}</td>
						<td>${item.type}</td>
						<td>${item.name}</td>
						<td>${item.quantity}x</td>
						<!-- td style="width: 60px;">
							<button type="button" class="btn btn-block btn-sm btn-outline-primary"
								onClick="cartLS.quantity(${item.id},-1)">-</button>
						</td>
						<td style="width: 60px;">
							<button type="button" class="btn btn-block btn-sm btn-outline-primary"
								onClick="cartLS.quantity(${item.id},1)">+</button>
						</td -->
						<td class="text-right">&euro; ${item.price},00</td>
						<td class="text-right"><a href="#" class="item-remover" onClick="setTimeout(function(){cartLS.remove(${item.id})},500); $(this).closest('tr').addClass('removing');"><i class="bi bi-trash3 text-danger ms-2"></i></a></td>
					</tr>`
				}).join("")
			$total.innerHTML = "&euro; " + cartLS.total() + ",00"
			$totalQuantity.innerHTML = totalQuantity
		}
		renderCart(cartLS.list())
		cartLS.onChange(renderCart)

